mapper.select:
SELECT t.id, t.partner_user_id, t.device_no, t.user_id, t.agreement_type, t.agreed, t.agreed_at, t.clicked_at_ms, up.mobile_no FROM user_agreement_record t INNER JOIN user_profile up ON up.id = t.user_id AND up.deleted_at IS NULL INNER JOIN ( SELECT a.agreement_type, MAX(a.id) AS max_id FROM user_agreement_record a INNER JOIN user_profile p ON p.id = a.user_id AND p.deleted_at IS NULL WHERE p.mobile_no = #{mobileNo}
AND a.agreement_type IN
#{type}
GROUP BY a.agreement_type ) latest ON t.id = latest.max_id ORDER BY t.agreement_type ASC
